"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/cohort.css";
import type { CSSProperties, HTMLAttributes } from "react";
import { cn } from "../../lib/cn";

export type CohortRow = {
  id: string;
  label: string;
  size?: number;
  values: readonly (number | null)[];
};

export type CohortProps = HTMLAttributes<HTMLDivElement> & {
  label: string;
  periods: readonly string[];
  rows: readonly CohortRow[];
  formatter?: (value: number) => string;
  showSize?: boolean;
};

export function Cohort({ label, periods, rows, formatter = (value) => `${(value * 100).toFixed(value >= 0.1 ? 0 : 1)}%`, showSize = true, className, ...props }: CohortProps) {
  return (
    <div className={cn("whatiuse-cohort", className)} role="region" aria-label={`${label} table`} tabIndex={0} {...props}>
      <table>
        <caption>{label}</caption>
        <thead><tr><th scope="col">Cohort</th>{showSize && <th scope="col">Users</th>}{periods.map((period) => <th scope="col" key={period}>{period}</th>)}</tr></thead>
        <tbody>{rows.map((row) => <tr key={row.id}><th scope="row">{row.label}</th>{showSize && <td>{row.size?.toLocaleString() ?? "—"}</td>}{periods.map((period, index) => {
          const value = row.values[index];
          const strength = typeof value === "number" ? Math.min(1, Math.max(0, value)) : 0;
          return <td key={period} data-empty={value === null || value === undefined || undefined} style={{ "--whatiuse-cohort-strength": strength } as CSSProperties} aria-label={typeof value === "number" ? `${row.label}, ${period}, ${formatter(value)}` : `${row.label}, ${period}, no data`}>{typeof value === "number" ? formatter(value) : "—"}</td>;
        })}</tr>)}</tbody>
      </table>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-cohort { min-width: 0; overflow: auto; border-radius: var(--whatiuse-radius-container); background: var(--whatiuse-bg-stage); }

.whatiuse-cohort:focus { outline: 0; }

.whatiuse-cohort table { width: 100%; min-width: 620px; border-collapse: separate; border-spacing: 3px; padding: 12px; font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-cohort caption { padding: 2px 16px 10px; text-align: left; color: var(--whatiuse-fg-default); font-weight: 590; }

.whatiuse-cohort th,
.whatiuse-cohort td { height: 32px; padding: 0 8px; border-radius: 5px; text-align: center; }

.whatiuse-cohort thead th { color: var(--whatiuse-fg-subtle); font-weight: 520; }

.whatiuse-cohort tbody th { min-width: 104px; color: var(--whatiuse-fg-muted); font-weight: 540; text-align: left; white-space: nowrap; }

.whatiuse-cohort td { background: color-mix(in srgb, var(--whatiuse-fg-default) calc(4% + var(--whatiuse-cohort-strength) * 22%), transparent); color: var(--whatiuse-fg-default); }

.whatiuse-cohort td[data-empty] { background: transparent; color: var(--whatiuse-fg-subtle); }
}
